import React from 'react'

const FeeStructure = (props) => {
    const feeData = props.feeData;
    if (!feeData || Object.keys(feeData).length === 0) {
        return (
            <div className="container my-5">
                <h2 className="text-center fw-bold mb-4">Fee Structure Overview</h2>
                <div className="alert alert-warning text-center rounded-4 shadow-sm">
                    <p className="text-center">No fee data available.</p>
                </div>
            </div>
        );
    }

    const classKeys = Object.keys(feeData);
    return (
        <>
            <div className="container mt-3 mb-3 rounded-5 pt-4 pb-2 text-color" style={{ backgroundColor: "FFF8E1" }}>
                <h1 className="text-center fw-bold mb-4">Fee Structure Overview</h1>

                {/* class Navigation links */}
                <div className="text-center mb-4">
                    {classKeys.map((key, index) => (
                        <a key={index} href={`#${key}`} className="btn text-white mx-1 mb-1 bg-color fw-semibold" style={{ scrollBehavior: "smooth"}}>
                            {feeData[key].classes || key.toUpperCase()}
                        </a>
                    ))}
                </div>

                {/* Fee Structure Cards */}
                {classKeys.map((key, index) => {
                    const section = feeData[key];
                    const total = section.rows.reduce((acc, curr) => acc + (curr.sum || 0), 0);

                    return (
                        <div key={index} id={key} className="card border-0 shadow-lg rounded-4 mb-2">
                            <div className="card-body bg-light rounded-4">
                                <h4 className="text-center fw-bold mb-3">{section.classes} fees 2025-2026</h4>

                                <div className="table-responsive">
                                    <table className="table table-bordered table-striped table-hover text-center align-middle">
                                        <thead className="table-success">
                                            <tr>
                                                <th>Particulars</th>
                                                <th>Frequency</th>
                                                <th>Amount</th>
                                                <th>Sum Annually</th>
                                            </tr>
                                        </thead>

                                        <tbody>
                                            {section.rows.map((item, idx) => (
                                                <tr key={idx}>
                                                    <td>{item.particular}</td>
                                                    <td>{item.frequency}</td>
                                                    <td>₹{item.amount?.toLocaleString() || 0}</td>
                                                    <td>₹{item.sum?.toLocaleString() || 0}</td>
                                                </tr>
                                            ))}
                                        </tbody>

                                        <tfoot className="fw-bold">
                                            <tr>
                                                <td colSpan="3" className="text-end">
                                                    Yearly Cost for Admission :-
                                                </td>
                                                <td className='bg-color text-white'>₹{total.toLocaleString()}</td>
                                            </tr>
                                        </tfoot>
                                    </table>
                                </div>
                            </div>
                        </div>
                    );
                })}
            </div>

            {/* Back to top link */}
            <div className="text-center m-4 ">
                <a href="#top" className="text-decoration-none fw-bold fs-4 text-color">
                    ↑ Back to top
                </a>
            </div>
        </>
    )
}

export default FeeStructure
