import React from 'react'

const Foundation = (props) => {
    return (
        <div className="container-fluid p-0 position-relative py-5 foundation-section ">
            {/* Image */}
            <img src={`${process.env.PUBLIC_URL}/${props.foundation.imgSrc}`} alt="School Banner" className="w-100 foundation-image"/>

            {/* Text overlay */}
            <div className="position-absolute top-50 start-50 translate-middle text-center text-dark px-3 my-4 foundation-text-bg" style={{width:"90%"}}>
                <p className="m-4 text-color" >{props.foundation.text}</p>
            </div>
        </div>
    )
}

export default Foundation;
