import React from 'react'

const Admission = () => {
  return (
    <div className="container-fluid py-5">
      <div className="text-center">
        <h1 className="fw-bold display-4 text-uppercase text-color mb-0">Admission Process</h1>
        <p className="fw-semibold text-dark-50 fs-4" style={{color: "#189e07ff"}}>Important Dates</p>
      </div>

      <div className="container mt-3 text-start">
        <h5 className="fw-bold text-color underline">Playschool and LKG</h5>

        <p className="fw-semibold m-0">
          Issue of Application forms for Playschool and LKG and Submission of filled up forms <i style={{color: "#ff0800ff"}}>(2nd January to 28th April 2025 – 8:30 am to 12:00 Noon)</i>
        </p>

        <p className="mt-4 m-0">
          Announcement of the list of the selected candidates on the School Notice Board, and
          Issue of Applications to the selected candidates and the last Date for Submission of Application. <i style={{color: "#ff0800ff"}}>(Announced soon)</i>
        </p>

        <p className="fw-semibold mt-3" style={{ color: "#00FF7F" }}>
         <i style={{color:"#000000"}}> Note:</i> Late applications are liable to be rejected. Issue of application form does not amount to offer of admission.
        </p>
      </div>
    </div>

  )
}

export default Admission
