import React from 'react'

const Objective = (props) => {
    return (
        <section className="mx-3 py-3 rounded-3">
            {/* Objective Section */}
            <div className="container py-4">
                <h2 className="fw-bold mb-3 underline text-color">{props.OurObjective.Heading}</h2>
                <ol className="text-start mx-auto bold-numbers px-5 fs-5" style={{ textAlign: "justify" }}>
                    {Object.values(props.OurObjective.objVals).map((item, index) => (
                        <li className="mb-2" style={{ textAlign: "justify" }} key={index}>{item}</li>
                    ))}
                </ol>
                <div className="container mt-5">
                    <h6 className="text-start ps-3 text-color fs-4 underline">{props.OurObjective.subHeading}</h6>
                    <p className="mx-auto ps-3 pe-4 fs-5" style={{ textAlign: "justify" }}>{props.OurObjective.paragraph}</p>
                </div>
            </div>
        </section>
    )
}

export default Objective
