import React from "react";

const OurVision = (props) => {
    return (
        <section className="py-3 mx-3 rounded-3">
            {/* Vision and Values */}
            <div className="container">
                <div className="row align-items-center g-5">
                    <h2 className="fw-bold mb-3 underline text-color">{props.OurVision.Heading}</h2>
                    <div className="col-md-6 mt-0">
                        <img
                            src={props.OurVision.image}
                            alt="Our Vision"
                            className="img-fluid rounded shadow"
                        />
                    </div>
                    <div className="col-md-6">
                        <p className="text-muted fs-5">
                            {props.OurVision.paragraph}
                        </p>
                        <h4 className="fw-semibold mt-4 text-color">{props.OurVision.CoreVAlues.subHeading}</h4>
                        <ul className="list-unstyled text-muted fs-5">
                            {Object.values(props.OurVision.CoreVAlues.values).map((item, index) => (
                                <li key={index}>{item}</li>
                            ))}
                        </ul>
                    </div>
                </div>
            </div>
        </section>
    )
}

export default OurVision;