import React,{useState} from 'react'

const WriteReviews = () => {
    const [imageName, setImageName] = useState("No file chosen, Please choose your image");

  const handleFileChange = (e) => {
    if (e.target.files.length > 0) {
      setImageName(e.target.files[0].name);
    }
  };
    return (
        <div className="container py-3 justify-content-center">
            <div className="row justify-content-center">
                <div className="col-lg-8 col-md-10 col-12">
                    <div className="d-flex flex-column justify-content-center align-items-center">
                        <h3 className="text-center mb-4 text-color">Write Your Reviews</h3>
                        <form className="form w-100 rounded-4">
                            <div className="input-group rounded-5 my-3">
                                <input  onChange={handleFileChange}  type="file" className="input rounded-2" accept="image/*" placeholder="select your image"/>
                                <label className="ms-2 mt-2 text-muted">{imageName}</label>
                            </div>
                            <div className="input-group rounded-5 my-3">
                                <input type="email" className="input rounded-2"/>
                                <label className="placeholders">Name</label>

                            </div>
                            <div className="input-group rounded-5 my-3">
                                <textarea className="input rounded-2" rows={5}></textarea>
                                <label className="placeholders">Message</label>
                            </div>
                            <div className="text-center">
                                <button type="submit" className="btn bg-color text-white px-4">
                                    Submit
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            </div>
        </div>
    )
}

export default WriteReviews;
