import React, { useEffect, useState } from 'react'
import { Link, useLocation } from 'react-router-dom';

const Navbar = (props) => {

    const [sticky, setSticky] = useState(false);

    useEffect(() => {
        const handleScroll = () => {
            if (window.scrollY > 250) {   // 200px = after banner
                setSticky(true);
            } else {
                setSticky(false);
            }
        };

        window.addEventListener("scroll", handleScroll);
        return () => window.removeEventListener("scroll", handleScroll);
    }, []);


    let location = useLocation();
    useEffect(() => {
    }, [location]);

    return (
        <div>
            <nav className={`navbar navbar-expand-lg shadow-sm navbar-color ${sticky ? "sticky-nav" : ""}`}>
                <div className="container-fluid">
                    <Link className="navbar-brand d-flex" to="/">
                        <img className="rounded navbar-logo" src={props.logoSrc} alt="School Logo" />
                        <p className="mb-0 text-uppercase justify-content-center align-items-center ps-2 py-2 navbar-logo-text fw-semibold">{props.SchoolName}</p>
                    </Link>
                    <button className="navbar-toggler" type="button" data-bs-toggle="collapse" data-bs-target="#navbarSupportedContent" aria-controls="navbarSupportedContent" aria-expanded="false" aria-label="Toggle navigation">
                        <span className="navbar-toggler-icon"></span>
                    </button>
                    <div className="collapse navbar-collapse ps-3 justify-content-end" id="navbarSupportedContent">
                        <ul className="navbar-nav mb-2 mb-lg-0">
                            <li className="nav-item">
                                <Link className={`nav-link py-0 pe-2 ${location.pathname === "/" ? "active" : ""}`} aria-current="page" to="/">{props.home}</Link>
                            </li>
                            <li className="nav-item dropdown">
                                <button className={`nav-link dropdown-toggle py-0 pe-2 ${location.pathname === "/academics/feeStructure" || location.pathname === "/academics/admission" || location.pathname === "/academics/alumni" ? "active" : ""}`} id="navbarDropdown" type="button" data-bs-toggle="dropdown" aria-expanded="false">{props.academics}</button>
                                <ul className="dropdown-menu p-0" aria-labelledby="navbarDropdown">
                                    <li className="m-0">
                                        <Link className={`dropdown-item ${location.pathname === "/academics/feeStructure" ? "active" : ""}`} to="/academics/feeStructure">
                                            {props.feeStructure}
                                        </Link>
                                    </li>
                                    <li className="m-0">
                                        <Link className={`dropdown-item ${location.pathname === "/academics/admission" ? "active" : ""}`} to="/academics/admission">
                                            {props.admission}
                                        </Link>
                                    </li>
                                    <li className="m-0">
                                        <Link className={`dropdown-item ${location.pathname === "/academics/alumni" ? "active" : ""}`} to="/academics/alumni">
                                            {props.alumni}
                                        </Link>
                                    </li>
                                </ul>
                            </li>
                            <li className="nav-item">
                                <Link className={`nav-link py-0 pe-2 ${location.pathname === "/gallery" ? "active" : ""}`} to="/gallery">{props.gallery}</Link>
                            </li>
                            <li className="nav-item">
                                <Link className={`nav-link py-0 pe-2 ${location.pathname === "/contact" ? "active" : ""}`} to="/contact">{props.contact}</Link>
                            </li>
                            <li className="nav-item">
                                <Link className={`nav-link py-0 pe-2 ${location.pathname === "/about" ? "active" : ""}`} to="/about">{props.about}</Link>
                            </li>
                        </ul>
                    </div>
                </div>
            </nav>
        </div>
    )
}

export default Navbar;
