import React from 'react'
import OurMission from './OurMission';
import OurVision from './OurVision';
import OurStory from './OurStory';
import Objective from './Objective';
import OurLeaders from './OurLeaders';

const About = (props) => {
    return (
        <div className="about-page my-5 rounded-5">
            {/* Hero Section */}
            <section className="about-hero position-relative text-center text-dark" >
                <div className="position-absolute top-50 start-50 translate-middle hero-overlay">
                    <h1 className="fw-bold display-5 text-nowrap text-color">{props.Heading}</h1>
                    <p className="lead">{props.subHeading}</p>
                </div>
            </section>
            <OurMission OurMission={props.ourMission} />
            <hr />
            <OurVision OurVision={props.ourVision} />
            <hr />
            <OurStory OurStory={props.ourStory} />
            <hr />
            <Objective OurObjective={props.ourObjective} />
            <hr />
            <OurLeaders OurLeaders={props.ourLeaders} />
        </div >
    )
}

export default About
