import React from 'react'

const Banner = (props) => {
    return (
        <div className='container-fluid bg-color text-light px-0 pt-2'>
            <div className="row gx-0 d-flex flex-column flex-lg-row justify-content-center">
                {/* ----logo & school name---- */}
                <div className='navbar-brand d-flex flex-column flex-lg-row justify-content-center align-items-center'>
                    <img className='me-3 pt-1 school-logo rounded' src={props.logoSrc} alt="School Logo" />
                    <div className='school-header text-light text-center px-2'>
                        <p className='mb-0 text-uppercase school-name'>{props.SchoolName}</p>
                    </div>
                </div>
                {/* ----top contact row---- */}
                <div className='d-flex justify-content-between align-items-center flex-wrap px-3 pb-2 w-100' style={{fontSize:"clamp(20px,5vm, 25px)"}}>
                    <a className="text-decoration-none text-light" href={`mailto:${props.schoolMail}`}>{props.schoolMail}</a>
                    <a className="text-decoration-none text-light" href={`tel:+${props.contactNo}`}>{props.contactNo}</a>
                </div>
            </div>
        </div>
    )
}

export default Banner
