import React from 'react'

const Branches = (props) => {
    const { heading, branches } = props.branches;
    const branchList = Object.values(branches);
    return (
        <div className="container text-center">
            <h2 className="fw-bold mb-5 text-color">{heading}</h2>
            <div className="row justify-content-center g-4">

                {/* <!-- Branch 1 --> */}
                <div className="row justify-content-center g-4">
                    {branchList.map((branch, index) => (
                        <div className="col-md-8 col-lg-6" key={index}>
                            <div className="position-relative branch-box">
                                <img src={`${process.env.PUBLIC_URL}/${branch.imgSrc}`} className="img-fluid rounded-4 shadow-sm" alt="Branch Jhajjar" />
                                <div className="branch-name text-uppercase text-color">{branch.address}</div>
                            </div>
                        </div>
                    ))}
                </div>

            </div>
        </div>
    )
}

export default Branches
