import React from 'react'

const OurMission = (props) => {
    return (
        <section className="container py-3 text-center">
            {/* Mission Section */}
            <h2 className="fw-bold mb-4 text-color">{props.OurMission.Heading}</h2>
            <p className="text-muted mx-auto fs-5" style={{ maxWidth: "1000px" }} dangerouslySetInnerHTML={{ __html: props.OurMission.paragraph }}></p>
        </section>
    )
}

export default OurMission
